package com.erp.account.modules.supplierquotation.controller;
import com.erp.account.common.dto.request.RequestWrapper; import com.erp.account.common.dto.response.ApiResponse; import com.erp.account.modules.supplierquotation.dto.*; import com.erp.account.modules.supplierquotation.service.SupplierQuotationService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List; import java.util.UUID;
@RestController @RequestMapping("/api/account/supplier-quotations") @RequiredArgsConstructor public class SupplierQuotationController { private final SupplierQuotationService service;
 @PostMapping public ResponseEntity<ApiResponse<SupplierQuotationResponse>> create(@RequestParam(required=false)UUID companyId,@Valid @RequestBody RequestWrapper<SupplierQuotationRequest>w){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success(service.create(companyId,w.unwrap()),"Supplier quotation created successfully"));}
 @GetMapping public ResponseEntity<ApiResponse<Page<SupplierQuotationResponse>>> list(@RequestParam(required=false)UUID companyId,@PageableDefault(sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return ResponseEntity.ok(ApiResponse.success(service.list(companyId,p),"Supplier quotations retrieved successfully"));}
 @GetMapping("/by-rfq/{rfqId}") public ResponseEntity<ApiResponse<List<SupplierQuotationResponse>>> compare(@PathVariable UUID rfqId,@RequestParam(required=false)UUID companyId){return ResponseEntity.ok(ApiResponse.success(service.compareByRfq(companyId,rfqId),"Supplier quotations compared successfully"));}
 @GetMapping("/{id}") public ResponseEntity<ApiResponse<SupplierQuotationResponse>> get(@PathVariable UUID id,@RequestParam(required=false)UUID companyId){return ResponseEntity.ok(ApiResponse.success(service.get(companyId,id),"Supplier quotation retrieved successfully"));}
 @PostMapping("/{id}/award") public ResponseEntity<ApiResponse<SupplierQuotationResponse>> award(@PathVariable UUID id,@RequestParam(required=false)UUID companyId){return ResponseEntity.ok(ApiResponse.success(service.award(companyId,id),"Supplier quotation awarded successfully"));}
}
